package com.neotvos.support;
import java.io.*;import java.nio.*;import java.security.*;import java.security.interfaces.*;import java.util.*;
public final class CompanionTest{
 static void check(boolean yes,String what){if(!yes)throw new AssertionError(what);}
 static byte[] packet(int cmd,int a,int b,byte[] data){int sum=0;for(byte x:data)sum+=x&255;ByteBuffer p=ByteBuffer.allocate(24+data.length).order(ByteOrder.LITTLE_ENDIAN);return p.putInt(cmd).putInt(a).putInt(b).putInt(data.length).putInt(sum).putInt(~cmd).put(data).array();}
 static class Wire implements AdbClient.Wire{ByteArrayInputStream in;ByteArrayOutputStream out=new ByteArrayOutputStream();boolean closed;Wire(byte[]...packets)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();for(byte[] p:packets)b.write(p);in=new ByteArrayInputStream(b.toByteArray());}public void readFully(byte[] b)throws Exception{int off=0;while(off<b.length){int n=in.read(b,off,b.length-off);if(n<0)throw new EOFException();off+=n;}}public void write(byte[] b)throws Exception{out.write(b);}public void close(){closed=true;}}
 public static void main(String[] args)throws Exception{
  KeyPairGenerator generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);KeyPair keys=generator.generateKeyPair();byte[] token=new byte[20];new SecureRandom().nextBytes(token);byte[] signed=AdbClient.sign(keys.getPrivate(),token);javax.crypto.Cipher c=javax.crypto.Cipher.getInstance("RSA/ECB/PKCS1Padding");c.init(javax.crypto.Cipher.DECRYPT_MODE,keys.getPublic());byte[] decoded=c.doFinal(signed);check(Arrays.equals(Arrays.copyOfRange(decoded,15,35),token),"RSA challenge signing");check(AdbClient.publicKey((RSAPublicKey)keys.getPublic()).length>700,"ADB public key struct");
  byte[] empty=new byte[0],hello=packet(AdbClient.CNXN,0x01000000,4096,empty);
  Wire auth=new Wire(packet(AdbClient.AUTH,1,0,token),packet(AdbClient.AUTH,1,0,token),hello);new AdbClient(auth,keys).close();ByteBuffer authOut=ByteBuffer.wrap(auth.out.toByteArray()).order(ByteOrder.LITTLE_ENDIAN);int signatures=0,pubs=0;while(authOut.remaining()>0){int cmd=authOut.getInt(),a=authOut.getInt();authOut.getInt();int n=authOut.getInt();authOut.getInt();authOut.getInt();if(cmd==AdbClient.AUTH&&a==2)signatures++;if(cmd==AdbClient.AUTH&&a==3)pubs++;authOut.position(authOut.position()+n);}check(signatures==1&&pubs==1,"Signature then authorization key");
  Wire shell=new Wire(hello,packet(AdbClient.OKAY,7,1,empty),packet(AdbClient.WRTE,7,1,"ATV R1\n".getBytes("UTF-8")),packet(AdbClient.CLSE,7,1,empty));AdbClient a=new AdbClient(shell,keys);check(a.shell("getprop ro.product.model").trim().equals("ATV R1"),"Shell response");a.close();
  Wire reuse=new Wire(hello,packet(AdbClient.OKAY,7,1,empty),packet(AdbClient.WRTE,7,1,"first".getBytes("UTF-8")),packet(AdbClient.CLSE,7,1,empty),packet(AdbClient.CLSE,7,1,empty),packet(AdbClient.OKAY,8,2,empty),packet(AdbClient.WRTE,8,2,"second".getBytes("UTF-8")),packet(AdbClient.CLSE,8,2,empty));a=new AdbClient(reuse,keys);check(a.shell("first").equals("first"),"First stream");check(a.shell("second").equals("second"),"Stale close ignored when opening next stream");a.close();
  byte[] apk=new byte[10001];new Random(5).nextBytes(apk);Wire install=new Wire(hello,packet(AdbClient.OKAY,9,1,empty),packet(AdbClient.OKAY,9,1,empty),packet(AdbClient.OKAY,9,1,empty),packet(AdbClient.OKAY,9,1,empty),packet(AdbClient.WRTE,9,1,"Success\n".getBytes("UTF-8")),packet(AdbClient.CLSE,9,1,empty));a=new AdbClient(install,keys);final long[] progress={0};check(a.install(new ByteArrayInputStream(apk),apk.length,(sent,total)->progress[0]=sent).contains("Success"),"Install response");check(progress[0]==apk.length,"Install progress");ByteBuffer sent=ByteBuffer.wrap(install.out.toByteArray()).order(ByteOrder.LITTLE_ENDIAN);ByteArrayOutputStream streamed=new ByteArrayOutputStream();boolean exec=false;while(sent.hasRemaining()){int cmd=sent.getInt();sent.getInt();sent.getInt();int n=sent.getInt();sent.getInt();sent.getInt();byte[] data=new byte[n];sent.get(data);if(cmd==AdbClient.OPEN)exec=new String(data,"UTF-8").startsWith("exec:cmd package install -r --user 0 -S 10001");if(cmd==AdbClient.WRTE)streamed.write(data);}check(exec&&Arrays.equals(apk,streamed.toByteArray()),"Binary APK streamed intact without shell quoting");a.close();
  byte[] bad=packet(AdbClient.CNXN,0,0,new byte[]{1});bad[16]=0;Wire malformed=new Wire(bad);try{new AdbClient(malformed,keys);throw new AssertionError("Corrupt packet accepted");}catch(IOException good){check(malformed.closed,"Failed handshake closed transport");}
  Wire tls=new Wire(packet(AdbClient.STLS,0,0,empty));try{new AdbClient(tls,keys);throw new AssertionError("TLS port mistaken for classic");}catch(IOException good){check(good.getMessage().contains("paired TLS"),"Clear TLS guidance");}
  Set<String> homes=new HashSet<>(Arrays.asList("org.vendor.home","com.android.tvlauncher"));for(String pkg:Arrays.asList("android","com.tvos.neo","com.neotvos.support","com.android.tv.settings","org.example.keyboard","org.example.providers","org.vendor.home","x;rm -rf /","bad"))check(!CleanupPolicy.canRemove(pkg,true,homes),"Protected: "+pkg);check(CleanupPolicy.canRemove("org.videolan.vlc",false,homes),"Optional preinstall");check(CleanupPolicy.canRemove("org.example.game",true,homes),"Third-party app");check(!CleanupPolicy.canRemove("com.vendor.service",false,homes),"Unknown system app");
  System.out.println("PASS: RSA authorization, shell exchange, binary streaming/install response, malformed/TLS rejection, cleanup policy");
 }
}
